            items.append(ContentItem(id: UUID(), title: title, year: year, rating: rating, description: desc, imageName: image, type: .series, duration: duration, episodesCount: episodes)) 
        }
        
        // Add cartoons last
        for (title, year, rating, desc, image, duration) in cartoons { 
            items.append(ContentItem(id: UUID(), title: title, year: year, rating: rating, description: desc, imageName: image, type: .cartoon, duration: duration, episodesCount: nil)) 
        }
        
        return items
    }
    
